    padding: 0;
    background: repeating-linear-gradient(
      -45deg,
      #f5f5f5,
      #f5f5f5 3px,
      #ececec 3px,
      #ececec 6px
    );
    font-family: 'Segoe UI', Arial, sans-serif;
    width: 1024px;
    height: 768px;
    position: relative;
    box-sizing: border-box;
  }

  h1.title {
    color: #c00000;
    font-size: 44px;
    font-weight: bold;
    text-align: center;
    margin: 30px 0 10px 0;
    letter-spacing: 1px;
  }

  .intro {
    font-size: 22px;
    color: #1a1a1a;
    margin: 0 60px 20px 60px;
    line-height: 1.4;
  }

  .content-row {
    display: flex;
    align-items: flex-start;
    margin-left: 40px;
    margin-right: 40px;
    gap: 20px;
  }

  .group {
    display: flex;
    align-items: stretch;
    position: relative;
  }

  .label-box {
    background-color: #2fa3b5;
    color: white;
    font-size: 24px;
