      <div class="label-box">SAME</div>
      <div class="info-box">
        <ul class="same-list">
          <li>Active ingredients</li>
          <li>Dosage form</li>
          <li>Route of administration</li>
          <li>Strength/ Concentration</li>
        </ul>
      </div>
    </div>

    <div class="group">
      <div class="label-box small">DIFFERENT</div>
      <div class="info-box">
        <ul class="different-list">
          <li>Shape</li>
          <li>Labeling</li>
          <li>Release mechanism</li>
          <li>Scoring configuration</li>
          <li class="spacer-item"></li>
          <li>Excipient</li>
        </ul>
      </div>
    </div>
  </div>

